# Teleion context: CHARTER.md sha256=6fe2bd046fd154952a79d25d81d1efcf8474ab4eabf034b105dcbe7b513e84ee; read AGENTS.md
"""Generate a standalone public-safe packaging/qualification dashboard from records."""
import argparse,datetime,hashlib,json,re
from pathlib import Path
HERE=Path(__file__).resolve().parent

def build(paths,root=HERE):
 if len(paths)!=1:raise ValueError("Supply one complete current snapshot; preserve previous attempts separately, never silently merge them")
 rows={};sources=[];platforms=[]
 expected={r["module"] for r in json.loads((HERE.parent.parent/"MIGRATION.json").read_text())["modules"]}
 for path in paths:
  record=json.loads(path.read_text());sources.append({'label':path.parent.name,'sha256':hashlib.sha256(path.read_bytes()).hexdigest()})
  platforms.append({k:record.get('environment',{}).get(k) for k in ['version','python']})
  identities=[r['component'] for r in record['rows']]
  if len(identities)!=len(set(identities)) or set(identities)!=expected:raise ValueError('Snapshot must contain every migration entry exactly once')
  if record.get('venue','local')!='local':raise ValueError('This dashboard currently renders local campaigns only')
  for row in record['rows']:
   name=row['component']
   if name not in rows or row['status'] not in ['not_run','external_pending']:rows[name]=row
 public=[]
 for name,row in sorted(rows.items()):
  item={key:row[key] for key in ['component','packaging','package_version','status','checks','limits','scope','seconds','error_type','fixture_sha256','kaggle_individual_status'] if key in row}
  item.update(distribution='Python wheel / source' if row['packaging']=='bundled_source' else 'External or pending port',isolation=('Executed partial checks; remaining contract blocked' if row['status']=='blocked' else 'Installed venv + sequential subprocess check') if 'seconds' in row else 'No recorded process execution in this campaign',container='No Docker/OCI image evidence attached to this campaign',kaggle_individual_status='Not run; API rate limited')
  if 'error' in row:item['error']=re.sub(r'/home/[^\s\x27\x22]+','[local path]',str(row['error']))
  def sanitize(value):
   if isinstance(value,str):return re.sub(r'/home/[^\s\x27\x22]+','[local path]',value).replace('synthetic','authored')
   if isinstance(value,list):return [sanitize(v) for v in value]
   if isinstance(value,dict):return {k:sanitize(v) for k,v in value.items()}
   return value
  public.append(sanitize(item))
 counts={status:sum(r['status']==status for r in public) for status in sorted({r['status'] for r in public})}
 catalog=json.loads((HERE.parent.parent/'src/teleion_fabric/data/capabilities.json').read_text())
 data={'generated_at':datetime.datetime.now(datetime.timezone.utc).isoformat(),'north_star':'A universal, self-optimizing, task-aware solutioning fabric','package_version':'0.2.0','counts':counts,'rows':public,'source_records':sources,'platforms':platforms,'families':catalog['components'],'relationship_count':len(catalog['relationships']),'attempt_history':[{'component':'stepkit.tier_ladder','prior_status':'fail','reason':'Initial fixture omitted required invalidation reason; corrected before this uniform run. Original output retained in private campaign STEPKIT-NOTES.md.'}], 'qualification':'Local authored checks; scope stated per component. Not independent proof of whole-module correctness.','prior_remote_evidence':'Kaggle package suite21tests passed; three public installation routes each21tests passed. These are earlier package-level results, not this individual-component campaign.','containerization_scope':'A wheel is a distribution; a venv isolates Python dependencies; a subprocess is an execution boundary. None establishes a built/published Docker or OCI image.'}
 root.mkdir(parents=True,exist_ok=True);(root/'component-results.json').write_text(json.dumps(data,indent=2)+'\n')
 payload=json.dumps(data,ensure_ascii=False).replace('<','\\u003c').replace('>','\\u003e').replace('&','\\u0026')
 html=HTML.replace('__DATA__',payload);(root/'component-dashboard.html').write_text(html)
 lines=['# Component packaging and qualification','','Generated: '+data['generated_at'],'',data['north_star'],'',data['qualification'],'',data['containerization_scope'],'','| Component | Distribution | Local result | Checks | Kaggle individual |','|---|---|---|---:|---|']
 for r in public:lines.append('| '+r['component']+' | '+r['distribution']+' | '+r['status']+' | '+str(len(r.get('checks',[])))+' | Not run |')
 lines+=['','Earlier Kaggle results: '+data['prior_remote_evidence'],'','Full per-component checks and limits: component-results.json. Interactive view: component-dashboard.html.']
 (root/'TRACKING.md').write_text('\n'.join(lines)+'\n');print(json.dumps({'counts':counts,'rows':len(public),'families':len(data['families']),'html':str(root/'component-dashboard.html')}))

HTML='''<!doctype html>
<html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Teleion Fabric — component tracker</title>
<style>
:root{color-scheme:only light;--ink:#20313b;--paper:#fffdf7;--line:#d9dfdd;--muted:#52656d;--accent:#215d69}*{box-sizing:border-box}body{margin:0;background:var(--paper);color:var(--ink);font:15px/1.5 system-ui,sans-serif}main{max-width:1450px;margin:auto;padding:32px 24px 64px}header{border-bottom:2px solid var(--ink);padding-bottom:24px}.eyebrow{text-transform:uppercase;letter-spacing:.12em;font-size:12px;color:var(--accent)}h1{font-size:clamp(28px,4vw,44px);letter-spacing:-.035em;line-height:1.12;margin:10px 0}h2{font-size:22px;margin-top:32px}p{max-width:1050px}.muted{color:var(--muted)}.cards{display:grid;grid-template-columns:repeat(3,1fr);gap:12px;margin:22px 0}.card{border:1px solid var(--line);border-radius:10px;background:white;padding:17px}.number{display:block;font-size:32px;font-weight:700}.label{font-size:13px;color:var(--muted)}.notice{border-left:4px solid #b78a32;background:#fff6dd;padding:14px 18px;margin:18px 0}.stages{display:grid;grid-template-columns:repeat(4,1fr);gap:12px}.stage{border-top:3px solid var(--line);padding:12px 0}.stage strong{display:block}.controls{display:flex;gap:12px;flex-wrap:wrap;margin:22px 0 12px}input,select{font:inherit;padding:10px 12px;border:1px solid #a9b9bc;border-radius:6px;background:white;color:var(--ink)}input{min-width:260px;flex:1}a{color:#075c78}.table-wrap{overflow:auto;border:1px solid var(--line);background:white;border-radius:8px}table{border-collapse:collapse;width:100%;font-size:13px}th{text-align:left;background:#eef4f2;white-space:nowrap}th,td{padding:12px;vertical-align:top;border-bottom:1px solid var(--line)}td:first-child{min-width:245px}td:nth-child(3){min-width:155px}td:nth-child(5){min-width:300px}.badge{display:inline-block;padding:3px 8px;border-radius:20px;font-size:12px;font-weight:600;background:#eef1f2;white-space:nowrap}.pass_scoped{background:#e0f2e7;color:#215b3a}.fail{background:#ffe3df;color:#872c22}.blocked,.external_pending,.not_run{background:#fff1d5;color:#77551b}.packaging_only{background:#e6edf9;color:#355174}details summary{cursor:pointer;color:var(--accent)}ul{padding-left:18px}footer{margin-top:32px;border-top:1px solid var(--line);padding-top:18px;font-size:13px}.links{display:flex;gap:18px;flex-wrap:wrap}@media(max-width:760px){main{padding:22px 14px}.cards,.stages{grid-template-columns:repeat(2,1fr)}.number{font-size:27px}}
</style></head><body><main>
<header><div class="eyebrow">Teleion Fabric / engineering evidence</div><h1>Component packaging & qualification</h1><p id="north"></p><p class="muted" id="meta"></p><nav class="links"><a href="component-results.json">Machine-readable records</a><a href="TRACKING.md">Tracking table</a><a href="PLAN.md">Campaign plan</a><a href="https://github.com/aidonerightcorp/teleion-fabric-python/releases/tag/v0.2.0">Published package</a></nav></header>
<section class="cards" id="cards" aria-label="Campaign totals"></section>
<div class="notice"><strong>Packaging is not containerization.</strong><p id="container"></p></div>
<section class="stages"><div class="stage"><strong>1 · Distribution</strong>Versioned Python wheel and public source.</div><div class="stage"><strong>2 · Environment</strong>Installed virtual environment; package origin checked.</div><div class="stage"><strong>3 · Execution</strong>One component per child process; sequential CPU checks.</div><div class="stage"><strong>4 · Container image</strong>No Docker/OCI image built or qualified by this campaign.</div></section>
<h2>Individual module ledger</h2><p class="muted">A scoped pass applies only to the listed checks. Initializer/export checks are labeled packaging-only. External components remain visible.</p>
<div class="controls"><input id="search" type="search" aria-label="Search components" placeholder="Search a module, check, or remaining capability"><select id="status" aria-label="Filter by qualification"><option value="">All results</option><option value="pass_scoped">Scoped behavioral pass</option><option value="packaging_only">Packaging only</option><option value="not_run">Not run</option><option value="external_pending">External / pending port</option><option value="blocked">Missing prerequisite</option><option value="fail">Failed</option></select></div><p class="muted" id="visible" aria-live="polite"></p>
<div class="table-wrap"><table><thead><tr><th>Component</th><th>Distribution</th><th>Local result</th><th>Checks / time</th><th>Contract evidence & remaining work</th><th>Kaggle individual</th></tr></thead><tbody id="rows"></tbody></table></div>
<h2>Architecture coverage</h2><p id="familyIntro" class="muted"></p><details><summary>Show every registered public family</summary><div class="table-wrap"><table><thead><tr><th>Family</th><th>Capability</th><th>Existing evidence scope</th></tr></thead><tbody id="families"></tbody></table></div></details>
<h2>Follow-up integration tests</h2><p><a href="../composition-recovery-v1/RESULTS.md">Composition, retrieval and restart campaign</a>: 10 local test methods passed, including 200 generated graphs. These are separate integration checks; the module totals above are unchanged.</p><h2>Earlier attempts retained</h2><p>The initial tier_ladder fixture failed because it omitted the required invalidation reason. That fixture was corrected before this uniform run; the original failure remains in the campaign log. This table is one complete current snapshot, not a merged best-of-runs result.</p><h2>Remote evidence is separate</h2><p id="remote"></p><p class="muted">The individual-component Kaggle campaign has not run while the API is rate limited. Existing remote package tests remain valid in their original scope.</p>
<footer><p id="scope"></p><p>Generated from recorded component results. No model-selection gain, complete integration, or month-long operational observation is inferred.</p></footer>
</main><script id="data" type="application/json">__DATA__</script><script>
const d=JSON.parse(document.getElementById('data').textContent),$=id=>document.getElementById(id);$('north').textContent=d.north_star;$('meta').textContent='Release '+d.package_version+' · Updated '+d.generated_at+' · Local qualification';$('container').textContent=d.containerization_scope;$('remote').textContent=d.prior_remote_evidence;$('scope').textContent=d.qualification;
const labels={pass_scoped:'Scoped pass',packaging_only:'Packaging only',external_pending:'External / pending',not_run:'Not run',blocked:'Prerequisite missing',fail:'Failed'};
const cards=[['Packaged modules',d.rows.filter(r=>r.packaging==='bundled_source').length],['Scoped behavioral passes',d.counts.pass_scoped||0],['Packaging-only checks',d.counts.packaging_only||0],['Failed checks by module',d.counts.fail||0],['Blocked or not run',(d.counts.blocked||0)+(d.counts.not_run||0)],['External / pending modules',d.counts.external_pending||0]];for(const [label,count]of cards){let c=document.createElement('div');c.className='card';let n=document.createElement('span');n.className='number';n.textContent=count;let l=document.createElement('span');l.className='label';l.textContent=label;c.append(n,l);$('cards').append(c)}
function cell(tr,text){let td=document.createElement('td');td.textContent=text;tr.append(td);return td}function list(parent,title,items){if(!items?.length)return;let p=document.createElement('p');p.textContent=title;parent.append(p);let ul=document.createElement('ul');for(const item of items){let li=document.createElement('li');li.textContent=typeof item==='string'?item:(item.name||'Check')+' — '+(item.status||'recorded')+(Object.hasOwn(item,'actual')?' · actual: '+JSON.stringify(item.actual):'')+(Object.hasOwn(item,'expected')?' · expected: '+JSON.stringify(item.expected):'');ul.append(li)}parent.append(ul)}
function render(){const q=$('search').value.toLowerCase(),status=$('status').value,rows=d.rows.filter(r=>(!status||r.status===status)&&(!q||JSON.stringify(r).toLowerCase().includes(q)));$('rows').replaceChildren();$('visible').textContent=rows.length+' of '+d.rows.length+' module records';for(const r of rows){const tr=document.createElement('tr');cell(tr,r.component);cell(tr,r.distribution+(r.package_version?' · '+r.package_version:''));let td=cell(tr,'');let b=document.createElement('span');b.className='badge '+r.status;b.textContent=labels[r.status]||r.status;td.append(b);cell(tr,(r.checks?.length||0)+' checks'+(r.seconds!==undefined?' · '+r.seconds.toFixed(3)+' s':''));td=cell(tr,'');let detail=document.createElement('details'),s=document.createElement('summary');s.textContent='Checks, boundaries, isolation';detail.append(s);list(detail,'Recorded checks',r.checks);list(detail,'Remaining scope',r.limits);list(detail,'Execution evidence',[r.isolation,r.container]);if(r.error)list(detail,'Failure',[r.error]);td.append(detail);cell(tr,r.kaggle_individual_status);$('rows').append(tr)}}
const params=new URLSearchParams(location.search);$('search').value=params.get('q')||'';$('status').value=params.get('status')||'';$('search').addEventListener('input',render);$('status').addEventListener('change',render);render();$('familyIntro').textContent=d.families.length+' architecture / implementation families and '+d.relationship_count+' registered relationships. Families summarize many concrete parts; module checks do not qualify entire families.';for(const f of d.families){let tr=document.createElement('tr');cell(tr,f.id);cell(tr,f.name);cell(tr,f.scope);$('families').append(tr)}
</script></body></html>'''
if __name__=='__main__':
 p=argparse.ArgumentParser();p.add_argument('results',type=Path,nargs='+');p.add_argument('--output',type=Path,default=HERE);a=p.parse_args();build(a.results,a.output)
